/* =====================================================================
   engine.extension.js  —  Engine.Extension   (offline-plan §9)

   Browser-extension generation + verification. Manifest V3, with adapters
   for WXT (default), Extension.js, Plasmo, and a plain no-build path.

     generate → build → package → launch Chromium → load unpacked
       → drive → inspect popup / content / service worker / storage /
         permissions / console → PASS / FAIL

   The plain path builds with zero dependencies (it's just a folder + a
   zip). WXT / Plasmo builds run when their CLI is present, else BLOCKED
   <TOOL>_REQUIRED. Loading the unpacked extension + driving it needs a
   Chromium + automation (Playwright) — BLOCKED PLAYWRIGHT_REQUIRED, never
   "unsupported".

   window.Engine.Extension
     ADAPTERS
     generate(spec)     -> [{ path, content }]
     validate(files?)   -> { ok, findings }   (MV3 static checks)
     verify(opts?)      -> Promise<{ status, stages, reason?, need? }>
     analyze()          -> writes .sovereign/extension-evidence.json
   ===================================================================== */
(function () {
  'use strict';
  var Engine = window.Engine || (window.Engine = {});
  var S = function () { return Engine.Sovereign; };
  var FS = function () { return Engine.FS; };
  function adapters() { return window.CSAdapters || null; }
  function fread(p) { try { return (FS() && FS().read(p)) || ''; } catch (_) { return ''; } }
  function has(p) { try { return !!(FS() && FS().isFile(p)); } catch (_) { return false; } }

  var ADAPTERS = ['plain', 'wxt', 'extensionjs', 'plasmo'];

  function norm(spec) {
    spec = spec || {};
    return {
      name: spec.name || 'sovereign-extension',
      title: spec.title || spec.name || 'Sovereign Extension',
      description: spec.description || spec.objective || 'A browser extension generated by CodeSovereign.',
      adapter: ADAPTERS.indexOf(spec.adapter) >= 0 ? spec.adapter : 'plain',
      permissions: Array.isArray(spec.permissions) && spec.permissions.length ? spec.permissions : ['storage'],
      hostPermissions: Array.isArray(spec.hostPermissions) ? spec.hostPermissions : [],
      contentMatches: Array.isArray(spec.contentMatches) && spec.contentMatches.length ? spec.contentMatches : ['https://*/*']
    };
  }

  function manifest(s) {
    return {
      manifest_version: 3,
      name: s.title,
      version: '0.1.0',
      description: s.description,
      action: { default_popup: 'popup.html', default_title: s.title },
      background: { service_worker: 'background.js', type: 'module' },
      permissions: s.permissions,
      host_permissions: s.hostPermissions,
      options_page: 'options.html',
      content_scripts: [{ matches: s.contentMatches, js: ['content.js'], run_at: 'document_idle' }],
      icons: { '16': 'icon.svg', '48': 'icon.svg', '128': 'icon.svg' },
      web_accessible_resources: [],
      minimum_chrome_version: '111'
    };
  }

  function baseFiles(s) {
    var m = manifest(s);
    var out = {};
    out['/manifest.json'] = JSON.stringify(m, null, 2) + '\n';
    out['/background.js'] = [
      "// service worker — generated by CodeSovereign Engine.Extension",
      "chrome.runtime.onInstalled.addListener(() => { chrome.storage.local.set({ installedAt: Date.now(), count: 0 }); });",
      "chrome.runtime.onMessage.addListener((msg, _sender, reply) => {",
      "  if (msg && msg.type === 'ping') { chrome.storage.local.get('count').then(({ count }) => { const n = (count || 0) + 1; chrome.storage.local.set({ count: n }); reply({ ok: true, count: n }); }); return true; }",
      "  reply({ ok: false });", "});", ""
    ].join('\n');
    out['/content.js'] = [
      "// content script — generated by CodeSovereign Engine.Extension",
      "(() => {",
      "  const badge = document.createElement('div');",
      "  badge.id = '__sovereign_ext__';",
      "  badge.textContent = " + JSON.stringify(s.title) + ";",
      "  badge.style.cssText = 'position:fixed;bottom:8px;right:8px;z-index:2147483647;font:12px system-ui;background:#111;color:#fff;padding:4px 8px;border-radius:6px;opacity:.85';",
      "  document.documentElement.appendChild(badge);",
      "  chrome.runtime.sendMessage({ type: 'ping' });", "})();", ""
    ].join('\n');
    out['/popup.html'] = '<!doctype html><meta charset="utf-8"><title>' + s.title + '</title>' +
      '<style>body{font:14px system-ui;width:240px;padding:12px;margin:0}button{padding:8px 12px;border:1px solid #1d4ed8;background:#1d4ed8;color:#fff;border-radius:7px;cursor:pointer}</style>' +
      '<h1 style="font-size:15px;margin:0 0 8px">' + s.title + '</h1><p id="status">…</p><button id="ping">Ping background</button><script src="popup.js"></script>';
    out['/popup.js'] = [
      "const st = document.getElementById('status');",
      "chrome.storage.local.get(['count', 'installedAt']).then(({ count, installedAt }) => { st.textContent = 'pings: ' + (count || 0) + (installedAt ? ' · installed ' + new Date(installedAt).toLocaleDateString() : ''); });",
      "document.getElementById('ping').addEventListener('click', () => { chrome.runtime.sendMessage({ type: 'ping' }, (r) => { st.textContent = 'pings: ' + (r && r.count); }); });", ""
    ].join('\n');
    out['/options.html'] = '<!doctype html><meta charset="utf-8"><title>' + s.title + ' — Options</title>' +
      '<style>body{font:14px system-ui;max-width:480px;margin:24px auto;padding:0 16px}label{display:block;margin:12px 0}input{padding:6px 8px;border:1px solid #767676;border-radius:6px;width:100%}</style>' +
      '<h1>Options</h1><label>API base URL<input id="apiBase" type="url" placeholder="https://api.example.com"></label>' +
      '<button id="save">Save</button><p id="saved"></p><script src="options.js"></script>';
    out['/options.js'] = [
      "const el = document.getElementById('apiBase');",
      "chrome.storage.local.get('apiBase').then(({ apiBase }) => { if (apiBase) el.value = apiBase; });",
      "document.getElementById('save').addEventListener('click', () => { chrome.storage.local.set({ apiBase: el.value }).then(() => { document.getElementById('saved').textContent = 'saved'; }); });", ""
    ].join('\n');
    out['/icon.svg'] = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128"><rect width="128" height="128" rx="24" fill="#1d4ed8"/><path d="M40 64l16 16 32-32" stroke="#fff" stroke-width="10" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>\n';
    out['/_locales/en/messages.json'] = JSON.stringify({ extName: { message: s.title }, extDesc: { message: s.description } }, null, 2) + '\n';
    out['/README.md'] = '# ' + s.title + '\n\nManifest V3 browser extension generated by CodeSovereign.\n\n' +
      '## Load unpacked\n\n1. `chrome://extensions` → enable Developer mode\n2. "Load unpacked" → select this folder\n\n' +
      '## Package\n\n```bash\nnode scripts/pack.js   # -> dist/' + s.name + '.zip\n```\n';
    out['/scripts/pack.js'] = [
      "'use strict';",
      "const fs = require('fs'); const path = require('path'); const zlib = require('zlib');",
      "const root = path.join(__dirname, '..'); const out = path.join(root, 'dist');",
      "fs.mkdirSync(out, { recursive: true });",
      "// minimal store-only zip",
      "function crc32(buf){let c=~0;for(let i=0;i<buf.length;i++){c^=buf[i];for(let k=0;k<8;k++)c=(c>>>1)^(0xEDB88320&-(c&1));}return ~c>>>0;}",
      "// only the extension's own assets belong in a store zip — never build dirs,",
      "// dependencies, VCS, coverage, or CodeSovereign's evidence store.",
      "const SKIP=/^(dist|node_modules|\\.git|\\.sovereign|target|coverage|\\.output|\\.wxt|build|out|\\.cache|src-tauri)$/;",
      "const INCLUDE=/\\.(json|js|mjs|css|html|png|svg|jpg|jpeg|gif|woff2?|ttf|txt|md)$/i;",
      "function walk(d,b){let r=[];for(const n of fs.readdirSync(d)){if(SKIP.test(n))continue;const p=path.join(d,n),rel=b?b+'/'+n:n;const st=fs.statSync(p);if(st.isDirectory())r=r.concat(walk(p,rel));else if(INCLUDE.test(n)&&st.size<5*1024*1024)r.push(rel);}return r;}",
      "const files=walk(root,'').filter((f)=>f!=='scripts/pack.js');const chunks=[],cd=[];let off=0;",
      "for(const f of files){const data=fs.readFileSync(path.join(root,f));const name=Buffer.from(f);const crc=crc32(data);",
      " const lh=Buffer.alloc(30);lh.writeUInt32LE(0x04034b50,0);lh.writeUInt16LE(20,4);lh.writeUInt16LE(0,6);lh.writeUInt16LE(0,8);lh.writeUInt32LE(0,10);lh.writeUInt32LE(crc,14);lh.writeUInt32LE(data.length,18);lh.writeUInt32LE(data.length,22);lh.writeUInt16LE(name.length,26);",
      " chunks.push(lh,name,data);",
      " const c=Buffer.alloc(46);c.writeUInt32LE(0x02014b50,0);c.writeUInt16LE(20,4);c.writeUInt16LE(20,6);c.writeUInt32LE(crc,16);c.writeUInt32LE(data.length,20);c.writeUInt32LE(data.length,24);c.writeUInt16LE(name.length,28);c.writeUInt32LE(off,42);",
      " cd.push(Buffer.concat([c,name]));off+=lh.length+name.length+data.length;}",
      "const cdb=Buffer.concat(cd);const end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50,0);end.writeUInt16LE(files.length,8);end.writeUInt16LE(files.length,10);end.writeUInt32LE(cdb.length,12);end.writeUInt32LE(off,16);",
      "fs.writeFileSync(path.join(out,'" + s.name + ".zip'),Buffer.concat([...chunks,cdb,end]));",
      "console.log('packed ' + files.length + ' files -> dist/" + s.name + ".zip');", ""
    ].join('\n');

    if (s.adapter === 'wxt') {
      out['/package.json'] = JSON.stringify({ name: s.name, private: true, type: 'module', scripts: { dev: 'wxt', build: 'wxt build', zip: 'wxt zip' }, devDependencies: { wxt: '^0.19.0' } }, null, 2) + '\n';
      out['/wxt.config.ts'] = "import { defineConfig } from 'wxt';\nexport default defineConfig({ manifest: " + JSON.stringify(manifest(s)) + " });\n";
    } else if (s.adapter === 'plasmo') {
      out['/package.json'] = JSON.stringify({ name: s.name, private: true, scripts: { dev: 'plasmo dev', build: 'plasmo build', package: 'plasmo package' }, dependencies: { plasmo: '^0.88.0' } }, null, 2) + '\n';
    } else if (s.adapter === 'extensionjs') {
      out['/package.json'] = JSON.stringify({ name: s.name, private: true, scripts: { dev: 'extension dev', build: 'extension build' }, devDependencies: { 'extension': '^2.0.0' } }, null, 2) + '\n';
    } else {
      out['/package.json'] = JSON.stringify({ name: s.name, private: true, scripts: { build: 'node scripts/pack.js', pack: 'node scripts/pack.js' } }, null, 2) + '\n';
    }
    return out;
  }

  function generate(spec) {
    var s = norm(spec);
    var f = baseFiles(s);
    return Object.keys(f).sort().map(function (p) { return { path: p, content: f[p] }; });
  }

  /* ---------------- MV3 static validation ---------------- */
  function validate(files) {
    var mtxt = files && files['/manifest.json'] ? files['/manifest.json'] : fread('/manifest.json');
    var findings = [];
    var m;
    try { m = JSON.parse(mtxt); } catch (_) { return { ok: false, findings: [{ rule: 'manifest-parse', impact: 'critical', detail: 'manifest.json is not valid JSON' }] }; }
    if (m.manifest_version !== 3) findings.push({ rule: 'mv3', impact: 'critical', detail: 'manifest_version must be 3' });
    if (!m.name || !m.version) findings.push({ rule: 'required', impact: 'critical', detail: 'name + version are required' });
    if (m.background && m.background.scripts) findings.push({ rule: 'mv3-background', impact: 'serious', detail: 'MV3 uses background.service_worker, not background.scripts' });
    if ((m.permissions || []).indexOf('<all_urls>') >= 0 || (m.host_permissions || []).indexOf('<all_urls>') >= 0) findings.push({ rule: 'broad-host', impact: 'serious', detail: '<all_urls> — request only the hosts the extension needs' });
    (m.permissions || []).forEach(function (p) {
      if (['tabs', 'webRequest', 'cookies', 'history', 'bookmarks', 'downloads'].indexOf(p) >= 0) findings.push({ rule: 'sensitive-permission', impact: 'moderate', detail: 'sensitive permission "' + p + '" — justify it in the store listing' });
    });
    if (m.content_scripts) m.content_scripts.forEach(function (cs) {
      if (!cs.matches || !cs.matches.length) findings.push({ rule: 'content-match', impact: 'serious', detail: 'a content script has no `matches`' });
      (cs.js || []).forEach(function (j) { if (files ? !files['/' + j] : !has('/' + j)) findings.push({ rule: 'missing-file', impact: 'critical', detail: 'content script references missing file: ' + j }); });
    });
    ['action.default_popup', 'options_page'].forEach(function (k) {
      var v = k.split('.').reduce(function (o, p) { return o && o[p]; }, m);
      if (v && (files ? !files['/' + v] : !has('/' + v))) findings.push({ rule: 'missing-file', impact: 'serious', detail: k + ' -> missing ' + v });
    });
    var crit = findings.filter(function (f) { return f.impact === 'critical'; }).length;
    return { ok: crit === 0, findings: findings, byImpact: findings.reduce(function (mm, f) { mm[f.impact] = (mm[f.impact] || 0) + 1; return mm; }, {}) };
  }

  function persist(res) {
    if (!S()) return;
    S().write('extension-evidence.json', {
      generatedAt: Date.now(), capability: 'browser-extension', support: 'SUPPORTED',
      status: res.status, reason: res.reason || null, need: res.need || null,
      adapter: res.adapter || null, stages: res.stages || null, validation: res.validation || null,
      manifestVersion: 3
    });
  }

  function verify(opts) {
    opts = opts || {};
    var v = validate(null);
    var A = adapters();
    if (!A || !A.run) {
      var b = { status: v.ok ? 'PARTIAL' : 'FAIL', reason: v.ok ? 'RUNTIME_BRIDGE_UNAVAILABLE' : 'MV3_VALIDATION_FAILED',
        need: v.ok ? 'the desktop app (build + load-unpacked run through the local bridge / Playwright)' : null,
        stages: { sourceGeneration: 'PASS', staticValidation: v.ok ? 'PASS' : 'FAIL', build: 'NOT_RUN', loadUnpacked: 'NOT_RUN' }, validation: v };
      persist(b); return Promise.resolve(b);
    }
    return Promise.resolve(A.run('extension', { adapter: opts.adapter || null, timeoutMs: opts.timeoutMs || undefined })).then(function (r) {
      r = r || { status: 'FAIL', reason: 'ADAPTER_NO_RESULT' };
      r.validation = r.validation || v;
      persist(r); return r;
    }, function (e) { var f = { status: 'FAIL', reason: 'ADAPTER_ERROR', detail: String(e && e.message || e), validation: v }; persist(f); return f; });
  }

  function analyze() {
    if (!has('/manifest.json')) {
      if (S()) S().write('extension-evidence.json', { generatedAt: Date.now(), present: false, capability: 'browser-extension', support: 'SUPPORTED', note: 'no extension in the workspace' });
      return { present: false };
    }
    var v = validate(null);
    var report = { generatedAt: Date.now(), present: true, capability: 'browser-extension', support: 'SUPPORTED',
      status: v.ok ? 'VALID' : 'INVALID', validation: v, manifestVersion: 3 };
    if (S()) S().write('extension-evidence.json', report);
    return report;
  }

  function load() { try { var vv = S() && S().read('extension-evidence.json'); return (vv && typeof vv === 'object') ? vv : null; } catch (_) { return null; } }

  Engine.Extension = { ADAPTERS: ADAPTERS, generate: generate, validate: validate, verify: verify, analyze: analyze, load: load, manifest: manifest };
  console.info('[Extension] MV3 browser-extension generator (WXT / Plasmo / plain) ready — Engine.Extension');
})();
